package net.civeira.phylax.feature.observe.observedprobe.infrastructure.repository;

import java.util.Iterator;
import java.util.List;
import java.util.function.BiFunction;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.feature.observe.observedprobe.domain.ObservedProbe;
import net.civeira.phylax.feature.observe.observedprobe.domain.gateway.ObservedProbeCursor;
import net.civeira.phylax.feature.observe.observedprobe.domain.gateway.ObservedProbeFilter;

class ObservedProbeSlider extends Slider<ObservedProbe> {

  /**
   * @autogenerated SlideGenerator
   */
  private final ObservedProbeCursor cursor;

  /**
   * @autogenerated SlideGenerator
   */
  private final ObservedProbeFilter filter;

  /**
   * @autogenerated SlideGenerator
   */
  private final BiFunction<ObservedProbeFilter, ObservedProbeCursor, Iterator<ObservedProbe>> gateway;

  /**
   * @autogenerated SlideGenerator
   * @param multi
   * @param limit
   * @param gateway
   * @param filter
   * @param cursor
   */
  ObservedProbeSlider(final Iterator<ObservedProbe> multi, final int limit,
      final BiFunction<ObservedProbeFilter, ObservedProbeCursor, Iterator<ObservedProbe>> gateway,
      final ObservedProbeFilter filter, final ObservedProbeCursor cursor) {
    super(multi, limit);
    this.gateway = gateway;
    this.filter = filter;
    this.cursor = cursor;
  }

  /**
   * @autogenerated SlideGenerator
   * @param observedProbes
   * @param limit
   * @return
   */
  @Override
  public Iterator<ObservedProbe> next(List<ObservedProbe> observedProbes, int limit) {
    ObservedProbe last = observedProbes.get(observedProbes.size() - 1);
    ObservedProbeCursor cr = this.cursor.withSinceUid(last.getUid()).withLimit(limit);
    return gateway.apply(this.filter, cr);
  }
}
